import { CodeView, Button } from "march/ui"
import { onCleanup } from "march"
import { rotateCcw } from "march/icons"

// kod kendini yazar: code bir erişimci, her tikte bir harf daha; satırlar ve renkler yazdıkça gelir
const SRC = `export function Merhaba() {
  let $ad = "March"
  return <h1>Merhaba, {$ad}!</h1>
}`

export function TypingCode() {
  let $n = 0
  const timer = setInterval(() => { if ($n < SRC.length) $n++ }, 45)
  onCleanup(() => clearInterval(timer))
  return <div sx={{ flex: "col", gap: 2 }}>
    <CodeView code={() => SRC.slice(0, $n)} lang="tsx" langLabel="Merhaba.tsx" copy={false} wrapButton={false} label="Kendini yazan kod" />
    <div sx={{ flex: ["row", "between"], gap: 2 }}>
      <span sx={{ text: "sm", color: "muted" }}>{$n} / {SRC.length} harf</span>
      <Button variant="ghost" size="sm" icon={rotateCcw} disabled={$n < SRC.length} on:click={() => $n = 0}>Baştan yaz</Button>
    </div>
  </div>
}

import { CodeView, Segmented, Card } from "march/ui"

// bir API belgesindeki örnek: aynı istek üç biçimde; geliştirici birini seçer, kopyalar, yapıştırır
const SNIPPETS: Record<string, { lang: string; file: string; code: string }> = {
  curl: { lang: "sh", file: "terminal", code: `# yeni sipariş
curl -X POST https://api.ornek.dev/v1/siparis \
  -H "Authorization: Bearer $TOKEN" \
  -d '{ "urun": "kahve", "adet": 2 }'` },
  fetch: { lang: "ts", file: "siparis.ts", code: `const yanit = await fetch("https://api.ornek.dev/v1/siparis", {
  method: "POST",
  headers: { Authorization: "Bearer " + token },
  body: JSON.stringify({ urun: "kahve", adet: 2 }),
})
const siparis = await yanit.json()` },
  yanit: { lang: "json", file: "201 Created", code: `{
  "id": "sp_8421",
  "durum": "hazırlanıyor",
  "tahmini": "12 dk"
}` },
}

export function ApiSnippet() {
  let $kind = "curl"
  return <Card title="Sipariş oluştur" subtitle="POST /v1/siparis">
    <div sx={{ flex: "col", gap: 2 }}>
      <Segmented aria-label="Örnek biçimi" value={$kind} onChange={(v: unknown) => $kind = String(v)}
        options={[{ value: "curl", label: "cURL" }, { value: "fetch", label: "fetch" }, { value: "yanit", label: "Yanıt" }]} />
      {() => {
        const s = SNIPPETS[$kind]!
        return <CodeView code={s.code} lang={s.lang} langLabel={s.file} copyLabel="Kopyala" wrapLabel="Kaydır" label={`${s.file} örneği`} />
      }}
    </div>
  </Card>
}

import { test, expect, renderTest } from "march/testing"
import { CodeViewLab } from "./CodeViewLab.tsx"

// CodeViewLab'in testleri: kaydedince Testler sekmesinde çalışır
test("Satırları kaydır'a basınca kod kayar ve düğme basılı durur", async () => {
  const s = renderTest(() => <CodeViewLab />)
  const wrap = await s.click("Satırları kaydır")
  expect(wrap.getAttribute("aria-pressed")).toBe("true")
  expect(s.get(".lab-main")?.classList.contains("is-wrapped")).toBe(true)
})

test("code bir erişimci: başlangıç değişince kod da değişir; tools içindeki Çalıştır sayar", async () => {
  const s = renderTest(() => <CodeViewLab />)
  expect(s.find("Sayaç kodu")?.textContent).toContain("let $n = 0")
  await s.click("Başlangıcı artır")
  expect(s.find("Sayaç kodu")?.textContent).toContain("let $n = 1")
  await s.click("Çalıştır")
  await s.click("Çalıştır")
  expect(s.sees("2 kez çalıştı")).toBe(true)
})

test("simge düğmeler: wrap ile kayık başlar, adları ipucu olur", () => {
  const s = renderTest(() => <CodeViewLab />)
  expect(s.find("Kaydır")?.getAttribute("aria-pressed")).toBe("true")
  expect(s.get(".lab-icons")?.classList.contains("is-wrapped")).toBe(true)
  expect(s.find("Kopyala")).not.toBe(null)
})

test("düz blok: renk, satır numarası, dil etiketi ve düğme yok; toolbar={false} çubuğu kaldırır", () => {
  const s = renderTest(() => <CodeViewLab />)
  expect(s.get(".lab-plain [class^='m-tok-']")).toBe(null)
  expect(s.get(".lab-plain .m-code-ln")).toBe(null)
  expect(s.get(".lab-plain .m-code-lang")).toBe(null)
  expect(s.all(".lab-plain button").length).toBe(0)
  expect(s.get(".lab-bare .m-code-bar")).toBe(null)
  expect(s.get(".lab-main .m-tok-kw")).not.toBe(null)
})
